func forwardTCP(hostPort int, guestIP string, guestPort int) error {
    destination := guestIP + ":" + strconv.Itoa(guestPort)
    cmd := exec.Command(
        "iptables", "-t", "nat", "-A", "PREROUTING",
        "-p", "tcp", "--dport", strconv.Itoa(hostPort),
        "-j", "DNAT", "--to-destination", destination,
    )
    return cmd.Run()
}
